INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','future-perfect-continuous','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"future-perfect-continuous","title":"Future continuous and future perfect","level":"B2","order":34,"summary":"Look ahead to an activity in progress, a completed result or a duration measured from a future point.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["An activity at a future moment","Completion by a future deadline","Duration up to a future point","Questions and negatives"],"rules":[{"title":"An activity at a future moment","explanation":"Use **will be + -ing** to picture an activity already in progress at a future moment. You are looking into the middle of it. This differs from will + base verb, which can simply predict an event or express a decision.","pattern":"At noon, we **will be travelling**.","commonMistakes":["A precise future time does not always require continuous; the intended viewpoint decides."],"examples":["Use future continuous: At ten tomorrow, we **will be preparing** the visitor guide.","Use future continuous: At ten tomorrow, we **will be restoring** the old portrait."],"skill":"form"},{"title":"Completion by a future deadline","explanation":"Use **will have + past participle** to look back from a future point at something expected to be complete. By means no later than that point. Until generally describes continuation up to a point, so it is not interchangeable with by.","pattern":"By noon, we **will have arrived**.","commonMistakes":["Will have arrived describes completion by a deadline; will arrive until noon does not express that meaning."],"examples":["Use future perfect simple: By Friday, they **will have prepared** the visitor guide.","Use future perfect simple: By Friday, they **will have restored** the old portrait."],"skill":"meaning"},{"title":"Duration up to a future point","explanation":"Use **will have been + -ing** for the duration of an activity measured at a future point. It combines future reference, perfect aspect and continuous aspect. The first auxiliary is will; the later forms stay have and been.","pattern":"By July, I **will have been working** here for a year.","commonMistakes":["State verbs usually favour future perfect simple: will have known, rather than will have been knowing."],"examples":["Use future perfect continuous: By noon, I **will have been preparing** the visitor guide for two hours.","Use future perfect continuous: By noon, I **will have been restoring** the old portrait for two hours."],"skill":"contrast"},{"title":"Questions and negatives","explanation":"Move **will** before the subject in a question. Put **not** after will in a negative. All later auxiliaries stay after the subject in their original order. In conversation, will not often becomes won’t.","pattern":"Will she **have finished**? / She **will not have finished**.","commonMistakes":["Do not change have to has after will, even with she, he or it."],"examples":["Choose the opening for a future-perfect question about the visitor guide: **Will** they have prepared it by Friday?","Choose the opening for a future-perfect question about the old portrait: **Will** they have restored it by Friday?"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"6fafba9a-88cb-5fa6-a1ec-107ba158eccc","topicSlug":"future-perfect-continuous","level":"B2","prompt":"Use future continuous: At ten tomorrow, we ____ the visitor guide.","choices":[{"id":"A","text":"will be preparing"},{"id":"B","text":"will preparing"},{"id":"C","text":"will been preparing"},{"id":"D","text":"will be prepared"}],"answerId":"A","hint":"Picture the activity **in progress at a future time**.","explanation":"Future continuous pictures an activity at that moment: **will be preparing**.","keywords":["future-in-progress"],"skill":"future-in-progress","contextKey":"future-perfect-continuous-1","fingerprint":"aea52f665ea284e27a8a3046162312fa6e0d14b3941edbc643f40a55357d678f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Picture the activity **in progress at a future time**.","Future continuous pictures an activity at that moment: **will be preparing**.","Choose **will be preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Future continuous pictures an activity at that moment: **will be preparing**.","B":"Be is needed before the -ing form.","C":"After will use base be, not been.","D":"This is a passive-shaped phrase, not the requested active continuous."}}},{"id":"0a8c783b-2a99-5f74-aaff-3a243d9fdb99","topicSlug":"future-perfect-continuous","level":"B2","prompt":"Use future perfect simple: By Friday, they ____ the visitor guide.","choices":[{"id":"A","text":"will has prepared"},{"id":"B","text":"will have preparing"},{"id":"C","text":"will had prepared"},{"id":"D","text":"will have prepared"}],"answerId":"D","hint":"By gives a future deadline. Build **will + have + participle**.","explanation":"The future perfect simple is **will have prepared**, looking back from Friday.","keywords":["future-completion"],"skill":"future-completion","contextKey":"future-perfect-continuous-1","fingerprint":"9237bc4c49cefc624359bc976f9003886d588b3ae36564795018a88b8614988f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["By gives a future deadline. Build **will + have + participle**.","The future perfect simple is **will have prepared**, looking back from Friday.","Choose **will have prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Have must remain base form after will.","B":"Perfect simple needs a past participle.","C":"Had cannot follow will directly.","D":"The future perfect simple is **will have prepared**, looking back from Friday."}}},{"id":"4b34a4dd-3586-5b8f-afd0-ff383e41068e","topicSlug":"future-perfect-continuous","level":"B2","prompt":"Use future perfect continuous: By noon, I ____ the visitor guide for two hours.","choices":[{"id":"A","text":"will have being preparing"},{"id":"B","text":"will been preparing"},{"id":"C","text":"will have be preparing"},{"id":"D","text":"will have been preparing"}],"answerId":"D","hint":"Combine the future auxiliary with **have been + -ing** to measure duration.","explanation":"The duration measured at noon is expressed by **will have been preparing**.","keywords":["future-duration"],"skill":"future-duration","contextKey":"future-perfect-continuous-1","fingerprint":"4d6011b4429aba6c6a46ae479ba5acaa8a7502231d8cc22a1a6974768bc2cc55","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Combine the future auxiliary with **have been + -ing** to measure duration.","The duration measured at noon is expressed by **will have been preparing**.","Choose **will have been preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Use the past participle been, not being, after have.","B":"Have is missing and will cannot take been directly.","C":"Have needs been, not base be.","D":"The duration measured at noon is expressed by **will have been preparing**."}}},{"id":"571a53f3-2612-536b-ac82-a0969bd0cca7","topicSlug":"future-perfect-continuous","level":"B2","prompt":"Choose the opening for a future-perfect question about the visitor guide: ____ they have prepared it by Friday?","choices":[{"id":"A","text":"Have"},{"id":"B","text":"Do"},{"id":"C","text":"Will have"},{"id":"D","text":"Will"}],"answerId":"D","hint":"In a multi-auxiliary question, move **only the first auxiliary**.","explanation":"Only **will** moves before the subject; have stays after they.","keywords":["future-question-order"],"skill":"future-question-order","contextKey":"future-perfect-continuous-1","fingerprint":"8cdfc90a643d792376935c720f1be471b26e35958b23f7e4a3443191654ccb48","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["In a multi-auxiliary question, move **only the first auxiliary**.","Only **will** moves before the subject; have stays after they.","Choose **Will**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The sentence already has have after they; the future auxiliary is missing.","B":"Do is not added when will is the first auxiliary.","C":"This would repeat have and put two auxiliaries before the subject.","D":"Only **will** moves before the subject; have stays after they."}}},{"id":"fdf47b52-04e3-575a-a61e-77d11e728d4e","topicSlug":"future-perfect-continuous","level":"B2","prompt":"Use future continuous: At ten tomorrow, we ____ the old portrait.","choices":[{"id":"A","text":"will been restoring"},{"id":"B","text":"will be restored"},{"id":"C","text":"will be restoring"},{"id":"D","text":"will restoring"}],"answerId":"C","hint":"Picture the activity **in progress at a future time**.","explanation":"Future continuous pictures an activity at that moment: **will be restoring**.","keywords":["future-in-progress"],"skill":"future-in-progress","contextKey":"future-perfect-continuous-2","fingerprint":"66bb439d22a233079263617e3439e16037d10877d5d08c24925a565139440352","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Picture the activity **in progress at a future time**.","Future continuous pictures an activity at that moment: **will be restoring**.","Choose **will be restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After will use base be, not been.","B":"This is a passive-shaped phrase, not the requested active continuous.","C":"Future continuous pictures an activity at that moment: **will be restoring**.","D":"Be is needed before the -ing form."}}},{"id":"232ebe9e-efaf-5a37-a165-5c70dee4ba96","topicSlug":"future-perfect-continuous","level":"B2","prompt":"Use future perfect simple: By Friday, they ____ the old portrait.","choices":[{"id":"A","text":"will have restored"},{"id":"B","text":"will has restored"},{"id":"C","text":"will have restoring"},{"id":"D","text":"will had restored"}],"answerId":"A","hint":"By gives a future deadline. Build **will + have + participle**.","explanation":"The future perfect simple is **will have restored**, looking back from Friday.","keywords":["future-completion"],"skill":"future-completion","contextKey":"future-perfect-continuous-2","fingerprint":"2398f9c85a19d66665b304112e92528ea535071fe0309707f2949c83ba1354c0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["By gives a future deadline. Build **will + have + participle**.","The future perfect simple is **will have restored**, looking back from Friday.","Choose **will have restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The future perfect simple is **will have restored**, looking back from Friday.","B":"Have must remain base form after will.","C":"Perfect simple needs a past participle.","D":"Had cannot follow will directly."}}},{"id":"022fa2bf-0240-5240-a0a0-f98e5b4a0f0a","topicSlug":"future-perfect-continuous","level":"B2","prompt":"Use future perfect continuous: By noon, I ____ the old portrait for two hours.","choices":[{"id":"A","text":"will have been restoring"},{"id":"B","text":"will have being restoring"},{"id":"C","text":"will been restoring"},{"id":"D","text":"will have be restoring"}],"answerId":"A","hint":"Combine the future auxiliary with **have been + -ing** to measure duration.","explanation":"The duration measured at noon is expressed by **will have been restoring**.","keywords":["future-duration"],"skill":"future-duration","contextKey":"future-perfect-continuous-2","fingerprint":"b0ede093eaba1e033f770ffa500e90799bbd5614a973859a53947cb79eb00381","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Combine the future auxiliary with **have been + -ing** to measure duration.","The duration measured at noon is expressed by **will have been restoring**.","Choose **will have been restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The duration measured at noon is expressed by **will have been restoring**.","B":"Use the past participle been, not being, after have.","C":"Have is missing and will cannot take been directly.","D":"Have needs been, not base be."}}},{"id":"0fcecceb-9ce0-53bf-a694-edbb90eaff19","topicSlug":"future-perfect-continuous","level":"B2","prompt":"Choose the opening for a future-perfect question about the old portrait: ____ they have restored it by Friday?","choices":[{"id":"A","text":"Have"},{"id":"B","text":"Do"},{"id":"C","text":"Will have"},{"id":"D","text":"Will"}],"answerId":"D","hint":"In a multi-auxiliary question, move **only the first auxiliary**.","explanation":"Only **will** moves before the subject; have stays after they.","keywords":["future-question-order"],"skill":"future-question-order","contextKey":"future-perfect-continuous-2","fingerprint":"7e1c4ce1b29ec0b30dfaf802ea981f2cd17bd4f5eaba7e53f194201f63f5bc1c","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["In a multi-auxiliary question, move **only the first auxiliary**.","Only **will** moves before the subject; have stays after they.","Choose **Will**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The sentence already has have after they; the future auxiliary is missing.","B":"Do is not added when will is the first auxiliary.","C":"This would repeat have and put two auxiliaries before the subject.","D":"Only **will** moves before the subject; have stays after they."}}},{"id":"78276c1b-126c-5d1c-a41e-e90a4be265c0","topicSlug":"future-perfect-continuous","level":"B2","prompt":"Use future continuous: At ten tomorrow, we ____ the garden fence.","choices":[{"id":"A","text":"will been measuring"},{"id":"B","text":"will be measured"},{"id":"C","text":"will be measuring"},{"id":"D","text":"will measuring"}],"answerId":"C","hint":"Picture the activity **in progress at a future time**.","explanation":"Future continuous pictures an activity at that moment: **will be measuring**.","keywords":["future-in-progress"],"skill":"future-in-progress","contextKey":"future-perfect-continuous-3","fingerprint":"d502991959d7a60b7755124ac27294c0d294394ac460ffb087f1747d151c9c9f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["b